int main(int argc, char *argv[]) {
    if (argc <= 1) {
        printf("Please provide an index as a command line argument.\n");
        return 0;
    }

    int index = atoi(argv[1]);

    // check if the provided index is valid
    if (index < 1 || index > argc - 1) {
        printf("Index out of bounds. Please provide a valid index.\n");
        return 0;
    }

    for(int i=1; i<=index; i++) {
        if(i==1) {
            printf("The first argument from the command line is: %s\n", argv[i]);
        } else {
            printf("The %dth argument from the command line is: %s\n", i, argv[i]);
        }
    }

    return 0;
}
```

