["Here's an example of how you could implement this in Python using the `re` module for regular expressions and the `urllib.parse` module to handle URLs:

```Python
import re
from urllib.parse import urlparse, urlunparse, parse_qs

class Redirector:
    def __init__(self):
        self.regex = None

    def compile_regex(self, pattern):
        self.regex = re.compile(pattern)

    def redirect(self, target_url):
        if not self.regex:
            return target_url
        parsed_target = urlparse(target_url)
        parsed_default = urlparse('http://default')

        if self.regex.match(parsed_target.path):
            # The target URL matches the regex, so use it as the redirect target
            return f'{parsed_target.scheme}://{parsed_target.netloc}{parsed_target.path}'
        else:
            # The target URL does not match, so use the default URL
            query = parse_qs(parsed_default.query)
            for key, value in self.regex.groupdict().items():
                if key in parsed_target.query:
                    query[key] = [value]
                elif value is not None:
                    query[key] = [value[0]]
            return urlunparse((parsed_default.scheme, parsed_default.netloc, parsed_default.path, 
                               '&'.join(f'{key}={value[0]}' for key, value in query.items()), parsed_default.fragment))

# Example usage
redirector = Redirector()
redirector.compile_regex(r'^/users/(?:edit|view)$')
print(redirector.redirect('http://example.com/users/edit'))  # Output: http://example.com/users/edit
print(redirector.redirect('http://example.com/settings'))  # Output: http://default/settings?user=view
```

In this code, the `Redirector` class has a method called `compile_regex` which compiles the regular expression once when you call it. Then the `redirect` method is used to redirect URLs based on whether they match the compiled regex or not.

The default URL and the target URL are parsed using the `urlparse` function from the `urllib.parse` module, then compared with the regex. If the regex matches, the original URL is returned; if it doesn't match, a new URL is constructed by combining parts of the default URL with query parameters from the target URL.

Note that the `groupdict` method of the compiled regex returns a dictionary of named groups in the regex pattern. This is used to populate the query string of the default URL."]

