                if confirm_password == 'pass1':  # You need to get the correct password from the session
                    users[new_email] = {'password': 'pass1', 'email': new_email}
                    del users[old_email]
                    return 'Email has been changed successfully!'
                else:
                    return 'Invalid password! Please try again.'
            else:
                return 'You are not logged in!'
        else:
            return 'Old email does not exist or new email is the same as old email.'
    else:
        return 'You are not logged in!'

if __name__ == '__main__':
