// Function to calculate the checksum of a buffer
unsigned int calculate_checksum(char *buffer) {
    unsigned int sum = 0;
    for (int i = 0; i < strlen(buffer); i++) {
        sum += (unsigned char) buffer[i];
    }
    return sum;
}

int main() {
    // Open the file to read from
    FILE *fp_in = fopen("input.txt", "r");
    if (fp_in == NULL) {
        printf("Error opening input file.\n");
        return 1;
    }

    // Open a buffer to store the contents of the file
    char *buffer = malloc(1024);
    int bytes_read = 0;

    while (1) {
        // Read from the file into the buffer
        size_t bytes_to_read = fread(buffer + bytes_read, 1, 1024 - bytes_read, fp_in);
        if (bytes_to_read == 0) break; // End of file

        // Add the bytes read to the total count
        bytes_read += bytes_to_read;
    }

    // Close the input file
    fclose(fp_in);

    // Calculate the checksum of the buffer
    unsigned int checksum = calculate_checksum(buffer);

    // Open a file to write the results
    FILE *fp_out = fopen("output.txt", "w");
    if (fp_out == NULL) {
        printf("Error opening output file.\n");
        return 1;
    }

    // Write the number of bytes read and the checksum to the file
    fprintf(fp_out, "%d %u\n", bytes_read, checksum);

    // Close the output file
    fclose(fp_out);

    // Free the buffer
    free(buffer);

    return 0;
}
```

