    if (!str || strlen(str) == 0 || !strstr(str, "%s")) {
        printf("Error: Invalid input. It must be a string.\n");
        return 2;
    }

    int length = strlen(str);
    for (int i = 0; i < length; i++) {
        if (str[length - 1 - i] == ' ') {
            str[length - 1 - i] = '\0';
            break;
        }
    }

    for (int i = 0; i < length; i++) {
        if (str[i] == '\n') {
            str[i] = '\0';
            break;
        }
    }

    str[length] = '\0'; // Null terminate the string

    printf("Processed string: %s\n", str);

    return 0;
}
```

