['Here's a simple C program that does exactly what you asked:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <arg>\n", argv[0]);
        return 1;
    }

    // Trim trailing whitespace characters from the argument
    int len = strlen(argv[1]);
    while(len > 0 && isspace(argv[1][len-1])) {
        len--;
    }
    char* trimmedArgv = malloc((len + 1) * sizeof(char));
    strncpy(trimmedArgv, argv[1], len);
    trimmedArgv[len] = '\0';

    // Print the trimmed argument
    printf("%s\n", trimmedArgv);

    free(trimmedArgv);

    return 0;
}
```

